using System;
using System.IO;
using System.Linq;
using EchoStation.Persistence;
using NUnit.Framework;
namespace EchoStation.Tests.Persistence
{
 public sealed class StationFileStoreTests
 {
  private string root;private StationFileStore store;
  [SetUp]public void Setup(){root=Path.GetFullPath(Path.Combine("Library","EchoStation","S2SaveTests",Guid.NewGuid().ToString("N")));store=new StationFileStore(root);TestContext.WriteLine("Isolated save directory: "+root);}
  [TearDown]public void Cleanup(){var parent=Path.GetFullPath(Path.Combine("Library","EchoStation","S2SaveTests"))+Path.DirectorySeparatorChar;Assert.That(Path.GetFullPath(root).StartsWith(parent,StringComparison.OrdinalIgnoreCase),Is.True);if(Directory.Exists(root)&&TestContext.CurrentContext.Result.Outcome.Status!=NUnit.Framework.Interfaces.TestStatus.Failed)Directory.Delete(root,true);}
  private void Write(double elapsed){var s=StationSaveJsonTests.Fresh();s.Elapsed=elapsed;Assert.That(store.TryWrite(s,out var error),Is.True,error);}
  [Test]public void F03_B01_MissingReadDoesNotCreateDirectoryAndFirstWriteIsComplete(){Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.Missing));Assert.That(Directory.Exists(root),Is.False);Write(1);Assert.That(store.Read().Data.Elapsed,Is.EqualTo(1));Assert.That(File.Exists(store.TemporaryPath),Is.False);Assert.That(File.Exists(store.BackupPath),Is.False);Assert.That(Path.GetFileName(store.PrimaryPath),Is.EqualTo("slot1.json"));}
  [Test]public void F03_B02_AtomicSecondWritePreservesPriorValidBackup(){Write(1);var first=File.ReadAllText(store.PrimaryPath);Write(2);Assert.That(store.Read().Data.Elapsed,Is.EqualTo(2));Assert.That(File.ReadAllText(store.BackupPath),Is.EqualTo(first));Assert.That(File.Exists(store.TemporaryPath),Is.False);}
  [Test]public void F03_B03_CorruptPrimaryFallsBackAndRewritePreservesRejectedOriginal(){Write(1);Write(2);var backup=File.ReadAllText(store.BackupPath);File.WriteAllText(store.PrimaryPath,"damaged-primary");var read=store.Read();Assert.That(read.Status,Is.EqualTo(StationReadStatus.Backup));Assert.That(read.Data.Elapsed,Is.EqualTo(1));Write(3);Assert.That(File.ReadAllText(store.BackupPath),Is.EqualTo(backup));var rejected=Directory.GetFiles(root,"slot1.json.rejected-*");Assert.That(rejected.Length,Is.EqualTo(1));Assert.That(File.ReadAllText(rejected[0]),Is.EqualTo("damaged-primary"));}
  [Test]public void F03_B04_DoubleCorruptionAndOrphanBadBackupNeverOverwrite(){Directory.CreateDirectory(root);File.WriteAllText(store.PrimaryPath,"bad-p");File.WriteAllText(store.BackupPath,"bad-b");Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.Invalid));Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(File.ReadAllText(store.PrimaryPath),Is.EqualTo("bad-p"));File.Delete(store.PrimaryPath);Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(File.ReadAllText(store.BackupPath),Is.EqualTo("bad-b"));Assert.That(File.Exists(store.PrimaryPath),Is.False);}
  [Test]public void F03_B05_FuturePrimaryOrBackupIsProtected(){Write(1);var future=File.ReadAllText(store.PrimaryPath).Replace("\"version\":1","\"version\":2");File.WriteAllText(store.PrimaryPath,future);Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.UnsupportedVersion));Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(File.ReadAllText(store.PrimaryPath),Is.EqualTo(future));File.Delete(store.PrimaryPath);File.WriteAllText(store.BackupPath,future);Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.UnsupportedVersion));Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(File.ReadAllText(store.BackupPath),Is.EqualTo(future));}
  [Test]public void F03_B06_LockedFileOrDirectoryCollisionNeverChangesValidPrimary(){Write(1);var original=File.ReadAllBytes(store.PrimaryPath);using(var locked=new FileStream(store.PrimaryPath,FileMode.Open,FileAccess.Read,FileShare.None)){Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.IoError));Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);}Assert.That(File.ReadAllBytes(store.PrimaryPath),Is.EqualTo(original));Directory.CreateDirectory(store.TemporaryPath);Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(File.ReadAllBytes(store.PrimaryPath),Is.EqualTo(original));Directory.Delete(store.TemporaryPath);}
  [Test]public void F03_B07_InvalidCandidateAndOversizedCorruptionPreserveExistingBytes(){Write(1);var old=File.ReadAllBytes(store.PrimaryPath);var bad=StationSaveJsonTests.Fresh();bad.Player.X=float.NaN;Assert.That(store.TryWrite(bad,out _),Is.False);Assert.That(File.ReadAllBytes(store.PrimaryPath),Is.EqualTo(old));File.WriteAllText(store.PrimaryPath,"{}"+new string(' ',StationSaveJson.MaximumBytes));var huge=new FileInfo(store.PrimaryPath).Length;Assert.That(store.Read().Status,Is.EqualTo(StationReadStatus.Invalid));Assert.That(store.TryWrite(StationSaveJsonTests.Fresh(),out _),Is.False);Assert.That(new FileInfo(store.PrimaryPath).Length,Is.EqualTo(huge));}
  [Test]public void F03_B08_InvalidBackupIsQuarantinedBeforeValidReplacement(){Write(1);var original=File.ReadAllText(store.PrimaryPath);File.WriteAllText(store.BackupPath,"broken-backup");Write(2);Assert.That(File.ReadAllText(store.BackupPath),Is.EqualTo(original));var rejected=Directory.GetFiles(root,"slot1.json.bak.rejected-*");Assert.That(rejected.Length,Is.EqualTo(1));Assert.That(File.ReadAllText(rejected[0]),Is.EqualTo("broken-backup"));Assert.That(store.Read().Data.Elapsed,Is.EqualTo(2));}
 }
}
